--
-- Table structure for table `barangay_inventory`
--

DROP TABLE IF EXISTS `barangay_inventory`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `barangay_inventory` (
  `inventory_id` int(11) NOT NULL AUTO_INCREMENT,
  `barangay_id` int(11) NOT NULL,
  `item_type` varchar(50) NOT NULL,
  `item_name` varchar(100) NOT NULL DEFAULT 'Food Packs',
  `unit` varchar(20) NOT NULL DEFAULT 'packs',
  `quantity_available` int(11) NOT NULL DEFAULT 0,
  `min_stock_level` int(11) NOT NULL DEFAULT 0,
  `last_updated` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `updated_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`inventory_id`),
  UNIQUE KEY `uq_brgy_item` (`barangay_id`,`item_type`),
  KEY `barangay_id` (`barangay_id`),
  KEY `updated_by` (`updated_by`),
  CONSTRAINT `fk_brgyinv_barangay` FOREIGN KEY (`barangay_id`) REFERENCES `barangays` (`barangay_id`) ON DELETE CASCADE,
  CONSTRAINT `fk_brgyinv_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`user_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

